// Calculate the centroid (center of mass) of a polygon's area
function centroid(points) {
    if (points.length < 3) {
        throw new Error("A polygon must have at least 3 vertices to calculate centroid");
    }

    let cx = 0;
    let cy = 0;
    let area = 0;

    const n = points.length;

    for (let i = 0; i < n; i++) {
        const j = (i + 1) % n;

        const cross = points[i].x * points[j].y - points[j].x * points[i].y;
        area += cross;

        cx += (points[i].x + points[j].x) * cross;
        cy += (points[i].y + points[j].y) * cross;
    }

    area = Math.abs(area) / 2;

    if (area === 0) {
        throw new Error("Cannot calculate centroid of a polygon with zero area");
    }

    cx = cx / (6 * area);
    cy = cy / (6 * area);

    return { x: cx, y: cy };
}

// Calculate the bounding box of a set of points
function boundingBox(points) {
    if (points.length === 0) {
        throw new Error("Cannot calculate bounding box of an empty set of points");
    }

    let minX = points[0].x;
    let minY = points[0].y;
    let maxX = points[0].x;
    let maxY = points[0].y;

    for (let i = 1; i < points.length; i++) {
        const point = points[i];
        if (point.x < minX) minX = point.x;
        if (point.x > maxX) maxX = point.x;
        if (point.y < minY) minY = point.y;
        if (point.y > maxY) maxY = point.y;
    }

    return { minX, minY, maxX, maxY };
}

// Export functions for use in other modules
module.exports = {
    distance,
    polygonArea,
    perimeter,
    centroid,
    boundingBox
};

