const { boundingBox } = require('./r4_geom.js');

// Test case 1: Normal points
console.log("Test 1: Normal points");
try {
    const points1 = [
        {x: 1, y: 2},
        {x: 3, y: 4},
        {x: 5, y: 6}
    ];
    const result1 = boundingBox(points1);
    console.log("Result:", result1);
    console.log("Expected: { minX: 1, minY: 2, maxX: 5, maxY: 6 }");
} catch (error) {
    console.log("Error:", error.message);
}

// Test case 2: Points with negative coordinates
console.log("\nTest 2: Negative coordinates");
try {
    const points2 = [
        {x: -1, y: -2},
        {x: 3, y: 4},
        {x: -5, y: 6}
    ];
    const result2 = boundingBox(points2);
    console.log("Result:", result2);
    console.log("Expected: { minX: -5, minY: -2, maxX: 3, maxY: 6 }");
} catch (error) {
    console.log("Error:", error.message);
}

// Test case 3: Single point
console.log("\nTest 3: Single point");
try {
    const points3 = [
        {x: 10, y: 20}
    ];
    const result3 = boundingBox(points3);
    console.log("Result:", result3);
    console.log("Expected: { minX: 10, minY: 20, maxX: 10, maxY: 20 }");
} catch (error) {
    console.log("Error:", error.message);
}

// Test case 4: Empty array
console.log("\nTest 4: Empty array");
try {
    const points4 = [];
    const result4 = boundingBox(points4);
    console.log("Result:", result4);
} catch (error) {
    console.log("Error:", error.message);
    console.log("Expected: Error for empty array");
}

// Test case 5: Points with same x coordinates
console.log("\nTest 5: Same x coordinates");
try {
    const points5 = [
        {x: 1, y: 2},
        {x: 1, y: 4},
        {x: 1, y: 6}
    ];
    const result5 = boundingBox(points5);
    console.log("Result:", result5);
    console.log("Expected: { minX: 1, minY: 2, maxX: 1, maxY: 6 }");
} catch (error) {
    console.log("Error:", error.message);
}

